import Redwood from 'redwood-sdk';

const client = new Redwood({ apiKey: process.env.REDWOOD_API_KEY });

async function runStream(prompt: string) {
  const controller = new AbortController();
  const stream = await client.streamGenerate({ prompt, signal: controller.signal });
  for await (const token of stream) {
    // apply backpressure by awaiting heavy work
    await handleToken(token);
  }
}

