// Go streaming example (context cancellation + buffered channel)
package main

import (
  "context"
  "fmt"
  "time"
  redwood "github.com/redwood-inference/go-sdk"
)

func main() {
  ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
  defer cancel()
  client := redwood.NewClient(redwood.Config{APIKey: "$REDWOOD_API_KEY"})
  ch := client.StreamGenerate(ctx, "Hello")
  for token := range ch {
    fmt.Print(token)
  }
}
